DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 100;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a curated site that still exists
    SELECT count(*) INTO bad
      FROM _site_type_merge_plan p LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'D25 site_type merge: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in the column
    SELECT count(*) INTO bad FROM _site_type_merge_plan p
     WHERE p.old_value IS NULL OR p.new_value = '' OR p.new_value = p.old_value
        OR length(p.new_value) > 100;
    IF bad > 0 THEN
        RAISE EXCEPTION 'D25 site_type merge: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _site_type_merge_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE u.site_type IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'D25 site_type merge: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 4: every planned row writes a value this lane owns (new value)
    SELECT count(*) INTO bad FROM _site_type_merge_plan p
     WHERE p.new_value NOT IN ('Castle/palace', 'Cave Structures', 'Church/cathedral', 'City/town/settlement', 'Fortress/citadel', 'Gate/archway/bridge', 'Mine/quarry', 'Necropolis/tombs complex', 'Residence/villa/farmhouse', 'Road/avenue/trackway', 'Theatre');
    IF bad > 0 THEN
        RAISE EXCEPTION 'D25 site_type merge: % planned row(s) write a value this lane does not own', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _site_type_merge_plan ORDER BY site_id LOOP
        moved := moved + apply_remediation_change(
            'unified_sites', 'site_type', 'id', r.site_id::text,
            r.old_value, r.new_value,
            'D25/site-type-merge', '2026-10-24_mechanical-site-type-merge-s001', r.change_key, 'authoritative', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'D25 site_type merge: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _site_type_merge_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE u.site_type IS DISTINCT FROM p.new_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'D25 site_type merge: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _site_type_merge_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'unified_sites'
       AND l.column_name = 'site_type'
       AND l.run_stamp = '2026-10-24_mechanical-site-type-merge-s001'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'D25 site_type merge: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = '2026-10-24_mechanical-site-type-merge-s001'
       AND (l.table_name <> 'unified_sites' OR l.column_name <> 'site_type');
    IF bad > 0 THEN
        RAISE EXCEPTION 'D25 site_type merge: this run stamp journalled % row(s) outside unified_sites.site_type', bad;
    END IF;

    RAISE NOTICE 'D25 site_type merge: % row(s) changed and journalled over % curated site(s)',
        moved, expected;
END $$;

COMMIT;

-- Post-commit read: the numbers the report quotes, from the database, not from the plan.
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = '2026-10-24_mechanical-site-type-merge-s001'
UNION ALL
SELECT 'journal rows for this test id', count(*)::text
  FROM remediation_change_log WHERE test_id = 'D25/site-type-merge'
UNION ALL
SELECT 'planned rows now holding the new value', count(*)::text
  FROM remediation_change_log l
 WHERE l.run_stamp = '2026-10-24_mechanical-site-type-merge-s001' AND l.table_name = 'unified_sites'
   AND l.column_name = 'site_type'
   AND EXISTS (SELECT 1 FROM unified_sites u
                WHERE u.id::text = l.row_pk AND u.site_type = l.new_value)
UNION ALL
SELECT 'curated rows whose site_type is a merged alias', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND site_type IN ('Castle', 'Cave', 'Church', 'Citadel', 'City', 'Fortress', 'Gate', 'Mine', 'Necropolis', 'Quarry', 'Road', 'Settlement', 'Theater', 'Town', 'Urban', 'Villa')
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds';
